/**
 * The director's type: for each directing style (src/lib/styles), what its
 * titles, credits and captions actually use — surveyed from the films, the
 * trailers and the channels — translated into a bundled face, a case, a
 * colour, an entrance and the roles the style puts on the frame. Where the
 * real typeface cannot be bundled (Futura, Gotham, Helvetica, Trajan…) an
 * open-licence stand-in is named in `standsFor`; where the survey found
 * nothing, `note` says the choice is an assumption.
 *
 * add_text_overlay {role} resolves through this; check_text holds the
 * supporting overlays to its faces, case and roles; film titles can have an
 * independent display treatment. guide/styles/<id>.md carries the surveyed
 * profiles in its "Type" section
 * (generated by scripts/gen-style-type.ts).
 */
import { styleById } from "../styles";
import type { FontId } from "./fonts";
import { TYPE_PRESETS, applyPreset, presetById, type OverlayFields, type TextAnimationId, type Transform, type TypePreset } from "./presets";

export type TypeRole = "title" | "card" | "intertitle" | "lower-third" | "caption" | "callout" | "citation" | "date" | "quote" | "label" | "credit";
export const TYPE_ROLES: TypeRole[] = ["title", "card", "intertitle", "lower-third", "caption", "callout", "citation", "date", "quote", "label", "credit"];

/** A role's overrides on top of a base preset. */
export interface RoleSpec {
  /** the generic preset this role starts from (src/lib/typography/presets) */
  preset: string;
  font?: FontId;
  transform?: Transform;
  sizePct?: number;
  sizePctVertical?: number;
  position?: string;
  color?: string;
  boxEnabled?: boolean;
  boxColor?: string;
  boxOpacity?: number;
  outlineW?: number;
  shadow?: number;
  animation?: TextAnimationId;
  holdS?: number;
  /** what this role is, in the style's own terms */
  use: string;
}

export interface TypeSystem {
  style: string;
  name: string;
  /** Optional type treatments, not creator-wide bans. */
  preferenceOnly?: boolean;
  /** the real typographic signature, in a sentence */
  signature: string;
  /** which bundled faces stand in for which real typefaces */
  standsFor: string;
  faces: FontId[];
  case: "sentence" | "upper" | "lower" | "tracked-upper";
  color: string;
  /** the field a card sits on (black unless the style paints one) */
  field: string;
  motion: TextAnimationId;
  defaultRole: TypeRole;
  roles: Partial<Record<TypeRole, RoleSpec>>;
  /** roles the style does not use (check_text warns) */
  never?: TypeRole[];
  /** the style puts nothing on the frame beyond a title (check_text warns on any overlay) */
  noText?: boolean;
  /** what the survey found (or did not) and how it was translated */
  note: string;
}

const GENERIC_ROLE_PRESET: Record<TypeRole, string> = { title: "title", card: "card-editorial", intertitle: "intertitle", "lower-third": "lower-third", caption: "caption-pop", callout: "callout", citation: "citation", date: "date-card", quote: "quote", label: "map-label", credit: "citation" };

const T = (t: Omit<TypeSystem, "name">, name: string): TypeSystem => {
  const reference = styleById(t.style);
  if (!reference?.craft) return { name, ...t };
  return {
    ...t, name: reference.name, preferenceOnly: true, never: [], noText: false,
    signature: reference.craft.typography,
    standsFor: "Bundled design starting points; exact fonts require a named work/version.",
    note: "Optional project treatments, not a verified career-wide typography system. " +
      "Keep title and supporting text coherent; source labels and accessibility captions are available. " +
      reference.craft.evidence.basis,
  };
};

