export const typeSystemFor = (styleId: string | null | undefined): TypeSystem | undefined => (styleId ? STYLE_TYPE.find((t) => t.style === styleId) : undefined);

/** A film title has its own treatment, even when a style only defines supporting text.
 * Explicit (including deliberately quiet) title designs take precedence. */
export function roleSpecFor(style: TypeSystem | undefined | null, role: TypeRole): RoleSpec | undefined {
  if (style?.roles[role]) return style.roles[role];
  if (!style || role !== "title") return undefined;
  return {
    preset: "title", font: style.faces[0],
    transform: style.case === "sentence" ? "none" : style.case,
    sizePct: 9, sizePctVertical: 6.5, position: "CENTER",
    boxEnabled: false, outlineW: 0, shadow: 0, holdS: 4,
    use: "the name of the standalone clip or film, given its own display moment; customize the title font and palette separately from supporting text",
  };
}

/** The preset id an overlay carries: "<style>:<role>" when made through a style, else the generic preset. */
export const roleOf = (preset: string | null | undefined): TypeRole | null => {
  if (!preset) return null;
  const i = preset.indexOf(":");
  const r = (i >= 0 ? preset.slice(i + 1) : ({ "lower-third": "lower-third", callout: "callout", "caption-pop": "caption", "card-archive": "card", "card-editorial": "card", title: "title", intertitle: "intertitle", quote: "quote", "date-card": "date", "map-label": "label", "mono-note": "caption", citation: "citation" } as Record<string, TypeRole>)[preset]) as TypeRole | undefined;
  return r && TYPE_ROLES.includes(r) ? r : null;
};

/** The preset a directing style reaches for first (its default role), or the generic lower-third. */
export function presetForStyle(styleId: string | null | undefined): TypePreset {
  const ts = typeSystemFor(styleId);
  const spec = ts?.roles[ts.defaultRole];
  return presetById(spec?.preset) ?? presetById("lower-third")!;
}

/**
 * Resolve a role for a frame: the style's role spec over its base preset (or
 * the generic preset for the role when the brief names no style), then the
 * caller's overrides. The overlay's `preset` records "<style>:<role>".
 */
export function applyRole(styleId: string | null | undefined, role: TypeRole, frame: { w: number; h: number }, text: string, startS: number, overrides: Parameters<typeof applyPreset>[4] = {}): OverlayFields {
  const ts = typeSystemFor(styleId);
  const spec = roleSpecFor(ts, role);
  const base = presetById(spec?.preset ?? GENERIC_ROLE_PRESET[role]) ?? TYPE_PRESETS[0];
  const merged: TypePreset = {
    ...base,
    ...(spec?.font ? { font: spec.font } : {}),
    ...(spec?.transform ? { transform: spec.transform } : {}),
    ...(spec?.sizePct != null ? { sizePct: spec.sizePct } : {}),
    ...(spec?.sizePctVertical != null ? { sizePctVertical: spec.sizePctVertical } : spec?.sizePct != null ? { sizePctVertical: +(spec.sizePct * 0.82).toFixed(1) } : {}),
    ...(spec?.position ? { position: spec.position } : {}),
    ...(spec?.color ? { color: spec.color } : ts ? { color: ts.color } : {}),
    ...(spec?.boxEnabled != null ? { boxEnabled: spec.boxEnabled } : {}),
    ...(spec?.boxColor ? { boxColor: spec.boxColor } : {}),
    ...(spec?.boxOpacity != null ? { boxOpacity: spec.boxOpacity } : {}),
    ...(spec?.outlineW != null ? { outlineW: spec.outlineW } : {}),
    ...(spec?.shadow != null ? { shadow: spec.shadow } : {}),
    ...(spec?.animation ? { animation: spec.animation } : ts ? { animation: ts.motion } : {}),
    ...(spec?.holdS != null ? { holdS: spec.holdS } : {}),
    id: ts ? `${ts.style}:${role}` : base.id,
  };
  return applyPreset(merged, frame, text, startS, overrides);
}
